        description = "Aparece en tu mano una llama parpadeante. Esta permanece hasta el final de la duración del conjuro y no te daña ni a ti ni a tu equipo. La llama emite luz brillante en un radio de 3 metros y luz tenue 3 metros más allá. El conjuro termina si lo lanzas de nuevo o si utilizas una acción para finalizarlo.\n\nTambién puedes atacar con la llama, pero esto termina el conjuro. Cuando lanzas este conjuro, o como acción en un turno posterior, puedes arrojar la llama a una criatura hasta a 9,1 metros de ti. Haz un ataque de conjuro a distancia. Si impactas, el objetivo recibe 1d8 de daño de fuego.\n\nEl daño del conjuro aumenta en 1d8 cuando alcanzas nivel 5 (2d8), nivel 11 (3d8) y nivel 17 (4d8).",
