        description = "Este hechizo canaliza una pequeña cantidad de energía oscura. Creas uno de los siguientes efectos mágicos dentro del alcance:\n\nElige un punto dentro de 9 metros. En un radio de 1,5 metros de ese punto, la luz brillante se vuelve tenue y la luz tenue se convierte en oscuridad durante 1 hora. Cualquier fuente de luz en el área ve su luz suprimida. Un objeto de hasta 30 cm cúbicos o un área de hasta 30 cm cuadrados que toques se descompone ligeramente. La madera se pudre, el vidrio se agrieta, las flores se marchitan. Si continúas tocándolo por 1 minuto, el objetivo se destruye. Este hechizo no afecta criaturas, objetos mágicos o materiales resistentes como el metal y la piedra. Puedes reanimar una bestia Tiny de CR 0 durante 1 hora. Es un no muerto que obedece tus órdenes, aunque no puede atacar. No puedes usar este efecto hasta que la criatura reanimada muera o el efecto termine. Enciendes instantáneamente una vela, antorcha o fogata. El fuego brilla en rojo, verde brillante o púrpura sombrío, a tu elección, hasta que se extinga. La punta de tu dedo brilla en verde o púrpura hasta 1 minuto. Mientras brilla, puedes usarlo para dibujar líneas luminosas en una superficie sólida, que duran 1 hora.\n\nPuedes tener hasta tres efectos no instantáneos activos a la vez al lanzar este hechizo varias veces, y puedes disipar un efecto como acción.",
