        mechanics = "Ataque de conjuro a distancia. Impacto: 2d8 + 1d6 de daño; el d8 que elijas fija el tipo (1 ácido, 2 frío, 3 fuego, 4 fuerza, 5 relámpago, 6 veneno, 7 psíquico, 8 trueno). Si los dos d8 salen iguales, salta a otra criatura a 9 metros con nueva tirada de ataque y de daño, y puede encadenarse; cada criatura solo una vez por lanzamiento. A nivel superior: +1d6 por nivel por encima del 1.",
        roleNotes = "Energía inestable que hiere de una forma distinta cada vez y a veces salta al siguiente.",
