        source = "Reglas basicas",
        icon = 136257,
        description = "Obtienes los servicios de un familiar, un espíritu que adopta una forma animal de tu elección: araña, comadreja, búho, caballito de mar, cangrejo, cuervo, gato, halcón, lagarto, murciélago, pez (mordedor), pulpo, rana (sapo), rata o serpiente venenosa. Aparece en un espacio libre dentro del alcance y tiene el perfil de la forma elegida, aunque su tipo es celestial, feérico o infernal (a tu elección) en vez de bestia.\n\nTu familiar actúa de forma independiente, pero siempre obedece tus órdenes. En combate hace su propia tirada de iniciativa y actúa en su propio turno. Un familiar no puede atacar, pero puede realizar otras acciones con normalidad.\n\nSi sus puntos de golpe se reducen a 0 desaparece sin dejar rastro físico alguno. Reaparecerá cuando lances este conjuro de nuevo. Mientras tu familiar esté a 30,5 metros de ti, puedes comunicarte con él telepáticamente. Además, puedes usar tu acción para ver a través de los ojos del familiar y oír lo que él oiga hasta el comienzo de tu próximo turno, ganando los beneficios de cualquier sentido especial que posea. Durante este tiempo, permanecerás sordo y ciego respecto a tus propios sentidos.\n\nPuedes usar tu acción para desconvocar temporalmente a tu familiar. Se retira a una dimensión de bolsillo, donde espera a ser convocado de nuevo. También puedes desconvocarlo para siempre. Mientras se encuentre temporalmente desconvocado, puedes usar una acción para hacer que reaparezca en un espacio desocupado a 9,1 metros o menos de ti.\n\nNo puedes tener más de un familiar al mismo tiempo. Si lanzas este conjuro cuando ya tienes uno haces que el actual adopte una forma nueva. Elígela de la lista anterior. Tu familiar se transforma en la criatura escogida.\n\nPor último, cuando lanzas un conjuro con un alcance de toque, puedes hacer que tu familiar sea el que toque a tu objetivo, como si él hubiera lanzado el conjuro. Tu familiar debe permanecer a 30,5 metros o menos de ti y usar su reacción para tocar al objetivo cuando lanzas el conjuro. Si este requiere una tirada de ataque, utiliza tu modificador de ataque para la tirada.",
        mechanics = "El familiar actua en su propia iniciativa y no puede atacar. Mientras este a 30 metros puedes comunicarte telepaticamente con el y usar una acción para ver y oir a través de sus sentidos hasta el inicio de tu siguiente turno.",
        roleNotes = "Un pequeño companero espiritual perfecto para exploracion, vigilancia y escenas de rol.",
    },
