        source = "Warcraft 5E Custom",
        icon = 136296,
        description = "Haces que un flujo de energía verde surja de los ojos y la boca de la criatura objetivo hacia tu mano, formando un lazo continuo de energía que los une.\n\nHaz un ataque de conjuro a distancia contra la criatura. Si impactas, el objetivo recibe 1d8 de daño necrótico y, en cada uno de tus turnos siguientes mientras dure el hechizo, puedes usar tu acción adicional para infligir 1d8 de daño necrótico automáticamente. Cada vez que el objetivo sufre daño por este hechizo, recuperas puntos de golpe igual a la mitad del daño infligido, y su máximo de puntos de golpe se reduce en la misma cantidad hasta que complete un descanso prolongado.\n\nSi fallas el ataque, puedes usar tu acción en turnos posteriores dentro de la duración del hechizo para intentar otro ataque de conjuro a distancia contra la misma criatura. El hechizo termina si usas tu acción para hacer otra cosa.\n\nEl hechizo también termina si el objetivo está a más de 9 metros de ti o tiene cobertura total al final de tu turno. Este hechizo no tiene efecto en constructos o no muertos.\n\nA niveles superiores. Cuando lanzas este hechizo con un espacio de nivel 2 o superior, el daño inicial aumenta en 1d8 por cada nivel de espacio de conjuro por encima del 1. El daño infligido como acción adicional también aumenta en 1d8 por cada dos niveles de espacio adicionales por encima del 1.º.",
        mechanics = "Provocas que un rayo verde de energía salga de los ojos y boca de la criatura objetivo y se dirija hacia tu mano, formando un flujo continuo de energía que los une. Haz un ataque de conjuro a distancia contra esa criatura. Si impactas, el objetivo recibe 1d8 de daño necrótico, y en cada uno de tus turnos durante la duración, puedes usar tu acción para infligir 1d8 de daño necrótico automaticamente. Cada vez que el objetivo recibe daño de este conjuro, ganas un numero de puntos de golpe igual a la mitad del daño infligido y su total de puntos de golpe maximo se reduce en la misma cantidad. Esta reduccion dura hasta que termine un descanso prolongado. El conjuro termina si usas tu acción para hacer otra cosa. También termina si el objetivo se encuentra fuera del alcance del conjuro o si tiene cobertura total de ti. Este conjuro no tiene efecto sobre criaturas que sean constructos o no muertos.",
