        description = "Cuando lanzas este conjuro, usas la cuerda para crear un círculo con un radio de 1,5 metros en la tierra o en el suelo. Cuando terminas de lanzar, la cuerda desaparece y el círculo se convierte en una trampa mágica.\n\nEsta trampa es casi invisible y requiere una prueba de Inteligencia (Investigación) exitosa contra tu CD de salvación de conjuros para poder discernirla.\n\nLa trampa se dispara cuando una criatura Pequeña, Mediana o Grande se desplaza a la tierra o al suelo en el radio del conjuro. Esa criatura debe tener éxito en una tirada de salvación de Destreza o ser izada mágicamente en el aire, dejándola colgando de cabeza 0,9 metros sobre el suelo. La criatura está apresada allí hasta que el conjuro termina.\n\nUna criatura apresada puede hacer una tirada de salvación de Destreza al final de cada uno de sus turnos, terminando el efecto sobre sí misma en un éxito. Alternativamente, lacriatura u otra persona que pueda alcanzarla puede usar una acción para hacer una prueba de Inteligencia (Conocimiento Arcano) contra tu CD de salvación de conjuros. En un éxito, el efecto apresado termina.\n\nDespués de que se dispara la trampa, el conjuro termina cuando ninguna criatura es apresada por ella.",
