        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136403,
        description = "Creas un arma espectral flotante dentro del alcance, que permanece hasta el final de la duración del conjuro o hasta que lo utilices de nuevo. Cuando lanzas este conjuro, puedes hacer un ataque de conjuro cuerpo a cuerpo contra una criatura que se encuentre a 1,5 metros o menos del arma. Si impactas, Ja criatura recibe tanto daño de fuerza como 1d8 + tu modificador de aptitud mágica.\n\nComo acción adicional puedes mover el arma hasta 6,1 metros y repetir el ataque contra una criatura que se encuentre a 1,5 metros o menos de ella.\n\nEl arma puede tener la forma que desees. Los clérigos cuyas deidades estén asociadas con un arma en particular (como San Cuthbert, conocido por su maza, o Thor, famoso por su martillo) utilizan esa arma como aspecto visual del conjuro.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 3 o más, el daño aumenta en 1d8 por cada dos niveles por encima de 2 que tenga el espacio que hayas empleado.",
        mechanics = "Creas un arma espectral flotante que ataca a una criatura. Supera un ataque de conjuro cuerpo a cuerpo contra inflige 1d8 puntos de daño por fuerza + tu mod. por característica mágica. El daño aumenta 1d8 por cada dos niveles por encima de 2. Acción adicional para moverla 6,1 metros",
        roleNotes = "",
