        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136405,
        description = "Lanzando huesos de dragón, tirando palitos con gemas incrustadas, echando las cartas o mediante otro método de adivinación, consigues que una entidad de otro mundo te otorgue un presagio sobre los resultados de una acción concreta que planees llevar a cabo en los próximos 30 minutos. El DM elige de entre los siguientes presagios:\n\n*Fortuna,* para resultados buenos.\n• *Desdicha,* para resultados malos.\n• *Fortuna y desdicha,* para resultados a la vez buenos y malos.\n• *Nada,* para resultados que no son particularmente buenos ni malos.\n\nEste conjuro no tiene en cuenta ninguna circunstancia que pueda alterar los resultados como, por ejemplo, el lanzamiento de otros conjuros, o la pérdida o encuentro de un compañero.\n\nSi se lanza dos veces o más antes del próximo descanso largo, hay una posibilidad acumulativa del 25 % por cada lanzamiento después del primero de recibir un presagio aleatorio. El DM realiza esta tirada en secreto.",
        mechanics = "Recibes un augurio de una entidad de otro mundo sobre el resultado de una acción especifica que planeas realizar en los 30 minutos siguientes. El DJ debe elegir como augurio \"dicha\", \"desdicha\", \"dicha y desdicha\" o \"nada\". Si se lanza el conjuro mas veces pueden salir lecturas aleatorias.",
        roleNotes = "",
