        damage = "",
        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136406,
        description = "Implantas una ilusión en una criatura u objeto que toques, de tal manera que los conjuros de adivinación proporcionan información falsa sobre este. El objetivo puede ser una criatura voluntaria o un objeto que puedas ver y que no lleva o vista otra criatura.\n\nCuando lanzas este conjuro, elige uno o los dos efectos siguientes. Permanecerán hasta el final de la duración del conjuro. Si lanzas este conjuro sobre la misma criatura u objeto cada día durante 30 días, eligiendo el mismo efecto cada vez, la ilusión durará hasta que sea disipada.\n\n***Aura falsa.*** Cambias el modo en que el objetivo se muestra a conjuros y efectos mágicos, como *detectar magia,* que perciben auras mágicas. Puedes hacer que un objeto no mágico parezca mágico, que un objeto mágico parezca no mágico o cambiar el aura del objeto para que aparente pertenecer a una escuela de magia específica de tu elección. Cuando utilizas este efecto en un objeto, puedes hacer que resulte obvio para cualquier criatura que coja y manipule el objeto que su esencia mágica es falsa.\n\n***Enmascarar.*** Cambias cómo el objetivo se muestra a conjuros y efectos mágicos que detectan tipos de criatura o alineamiento, como los Sentidos Divinos del paladín o el conjuro *símbolo.* Elige un tipo de criatura o un alineamiento.\n\nEl resto de conjuros y efectos mágicos tratarán al objetivo como si fuera una criatura de ese tipo o alineamiento.",
        mechanics = "Implantas una ilusion en una criatura voluntaria u objeto para que los conjuros de adivinacion revelen información falsa sobre el. Puedes simular que un objeto mágico es no mágico y viceversa o hacer que los conjuros que detectan tipos que criatura lo detecten del tipo o alineami",
        roleNotes = "",
    },
