        icon = 136408,
        description = "Implantas un mensaje en un objeto dentro del alcance, que será pronunciado en voz alta cuando se cumpla la condición de activación. Eliges un objeto que puedas ver y que no lleva o vista otra criatura. Después dices el mensaje, que debe estar formado por 25 palabras o menos, aunque puede ser retransmitido durante, como mucho, 10 minutos. Por último, determinas las circunstancias que activarán el conjuro para entregar tu mensaje.\n\nCuando se den estas circunstancias, una boca mágica aparecerá en el objeto y recitará el mensaje, con tu voz y con el mismo volumen que utilizaste. Si el objeto que eliges tiene una boca o algo que parezca una boca (como la de una estatua, por ejemplo), la boca mágica aparecerá ahí, con lo que parecerá que las palabras son pronunciadas por la boca del objeto. Cuando lanzas este conjuro, puedes hacer que termine después de entregar el mensaje o que permanezca y el mensaje sea repetido cada vez que ocurran las circunstancias que lo activan.\n\nEstas circunstancias pueden ser tan generales o detalladas como quieras, pero deben estar basadas en condiciones visuales o auditivas que ocurran a 9,1 metros o menos del objeto. Por ejemplo, puedes hacer que la boca hable cuando una criatura se acerque a menos de 9,1 metros o cuando suene una campana plateada dentro de esa distancia.",
        mechanics = "Colocas un mensaje de hasta 25 palabras en un objeto, el cual se emitira con tu voz y al mismo volumen que lo dijiste cuando se cumpla la condicion visual o auditiva que establezcas (que ocurra a 9,1 metros o menos del objetivo). Puedes decidir que el conjuro termine después o que e",
