        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136409,
        description = "Elige un objeto manufacturado de metal, como un arma de metal o una armadura media o pesada de metal que puedas ver dentro del alcance. Haces que dicho objeto se ponga al rojo vivo. Cualquier criatura en contacto físico con el objeto recibe 2d8 de daño de fuego cuando lanzas el conjuro. Hasta el final del conjuro, puedes usar una acción adicional en cada uno de tus turnos para causar este daño de nuevo.\n\nSi una criatura está vistiendo o portando el objeto y sufre el daño, deberá tener éxito en una tirada de salvación de Constitución o soltarlo, si es que puede. Si no lo suelta, tiene desventaja en tiradas de ataque y pruebas de característica hasta el comienzo de tu próximo turno.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 3 o más, el daño aumenta en 1d8 por cada nivel por encima de 2 que tenga el espacio que hayas empleado.",
        mechanics = "Calientas al rojo vivo cualquier objeto construido en metal. Cualquier criatura en contacto recibe 2d8 puntos de daño y debe superar una TS de Constitución o soltarlo. Puedes usar una acción adicional en tus siguientes turnos para repetir el daño. El daño aumenta 1d8 por nivel superior.",
