        mechanics = "Reprimes emociones fuertes en un radio de 6,1 metros de tu posición. Los humanoides afectados tienen que superar una TS de Carisma. Si fallan, puedes eliminar los estados hechizado o asustado, o hacer que sean los objetivos sean hostiles o indiferentes hacia criaturas de tu elección",
