        description = "Puedes leer los pensamientos de algunas criaturas hasta que termine el conjuro. Cuando lanzas el conjuro y como acción en los turnos siguientes hasta que el conjuro termine, puedes concentrar tu mente en una criatura que puedas ver a 9,1 metros o menos de ti. Si el objetivo elegido tiene Inteligencia 3 o menos o no habla ningún idioma, no se verá afectado.\n\nDe entrada, conoces los pensamientos superficiales de la criatura: lo que ocupa su mente en ese momento. Como acción, puedes concentrar tu voluntad en los pensamientos de otro objetivo o intentar sondear en profundidad los de la misma criatura. Si sondeas, el objetivo debe hacer una tirada de salvación de Sabiduría. Si fracasa, obtienes conocimientos sobre sus pensamientos, su estado emocional o algo que ocupe un lugar importante en su mente (una preocupación, o algo que ame u odie). Si tiene éxito, el conjuro termina. En cualquier caso, el objetivo sabe que estás sondeando su mente y, a menos que tu atención se torne hacia otra mente, podrá utilizar su acción en su turno para realizar una tirada enfrentada de Inteligencia; si tiene éxito, el conjuro termina.\n\nLas preguntas hechas verbalmente al objetivo afectan a sus pensamientos, por lo que este conjuro es especialmente efectivo como parte de un interrogatorio.\n\nTambién puedes emplear el conjuro para detectar la presencia de criaturas pensantes que no puedas ver. Cuando lanzas el conjuro, o como una acción antes del final de la duración del mismo, puedes buscar pensamientos en un radio de 9,1 metros a tu alrededor. Este efecto es capaz de atravesar la mayoría de las barreras, pero se ve bloqueado por 0,6 metros de piedra, 5,1 cm de cualquier metal que no sea plomo o una fina lámina de plomo. Si la criatura elegida tiene Inteligencia 3 o menos o no habla ningún idioma, no puedes detectarla.\n\nUna vez detectas su presencia de esta manera, puedes leer los pensamientos de la criatura hasta el final de la duración del conjuro de la manera descrita más arriba, incluso aunque no puedas verla, pero tiene que permanecer dentro del alcance.",
        mechanics = "Al lanzar el conjuro y como acción en tus siguientes turnos, lees pensamientos superficiales de una criatura que puedas ver hasta a 9,1 metros. En cada acción, puedes concentrarte en una criatura (contra TS de Sabiduría) o cambiar a otra. También puedes detectar a criaturas pensant",
        roleNotes = "",
    },
