        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136416,
        description = "Puedes sentir la presencia de cualquier trampa dentro del alcance que esté en tu línea de visión. En lo que a este conjuro respecta, una trampa incluye cualquier objeto que fuera a causar un efecto súbito o inesperado que tú consideres dañino o indeseable, y que fuera creado con ese propósito. Por tanto, el conjuro detectará un área afectada por el conjuro *alarma,* un *glifo custodio* o una trampa mecánica como un pozo, pero no revelará una zona endeble del suelo, un techo inestable o un socavón oculto.\n\nEste conjuro simplemente alerta de la existencia de una trampa. No te transmite la localización de cada trampa, pero sí la índole general del peligro potencial.",
        mechanics = "Sientes la presencia (pero no la ubicacion exacta) de cualquier trampa dentro del alcance y en tu línea de visión. Se entiende como trampa cualquier cosa que podria provocar un efecto repentino o inesperado que consideras danino o indeseable preparada intencionalmente por su crea",
        roleNotes = "",
