        mechanics = "Creas marana de palabras de distraccion. Las criaturas que elijas y puedan oirte realizan una TS de Sabiduría. Tienen ventaja si están luchando contra tus companeros y tu. Si fallan, tienen desventaja en las pruebas de Sabiduría (Percepción) para percibir a alguien que no seas tu",
