        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136419,
        description = "Una esfera de fuego de 1,5 metros de diámetro aparece en un espacio libre a tu elección dentro del alcance y se mantiene hasta el final de la duración del conjuro. Cualquier criatura que acabe su turno a 1,5 metros o menos de la esfera debe hacer una tirada de salvación de Destreza. Sufrirá\n\n2d6 de daño de fuego si falla la tirada o la mitad del daño si la supera.\n\nComo acción adicional, puedes mover la esfera hasta 9,1 metros a una nueva localización dentro del alcance. Si embistes con la esfera a una criatura, esta debe hacer la tirada de salvación contra el daño de la esfera, que ya no podrá moverse más durante este turno.\n\nCuando desplazas la esfera, puedes moverla por encima de barreras de hasta 1,5 metros de alto y hacer que salte hoyos de hasta 3 metros de ancho. Además, la esfera prende cualquier objeto inflamable que no vista o lleve alguien, y emite luz brillante en un radio de 6,1 metros y luz tenue en un radio de 6,1 metros más.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 3 o superior, el daño aumenta en 1d6 por cada nivel por encima de 2 que tenga el espacio que hayas empleado.",
        mechanics = "Creas una esfera de fuego de 1,5 metros de diametro. Criatura que termine su turno a 1,5 metros de la esfera o sea impactado por ella debe hacer una TS de Des. Recibe 2d6 de daño de fuego si falla y la mitad si tiene éxito. El daño aumenta 1d6 por nivel por encima de 2. Puedes moverla 30",
