        description = "Un súbito y fuerte tañido, de una intensidad dolorosa, brota de un punto de tu elección que se encuentre dentro del alcance. Todas las criaturas en una esfera de 3 metros centrada en el punto deben hacer una tirada de salvación de Constitución. Sufrirán 3d8 de daño de trueno si fallan la tirada o la mitad del daño si la superan. Una criatura hecha de un material inorgánico, como piedra, cristal o metal, tiene desventaja en esta tirada de salvación.\n\nUn objeto no mágico que no lleve o vista alguien también recibirá el daño si se encuentra dentro del área del conjuro.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 3 o mayor, el daño aumenta en 1d8 por cada nivel por encima de 2 que tenga el espacio que hayas empleado.",
