        source = "Reglas basicas",
        icon = 136423,
        description = "Evocas una hoja ardiente en tu mano libre. Esta es similar en tamaño y forma a una cimitarra y permanece hasta el final de la duración del conjuro. Si sueltas la hoja, desaparecerá, pero puedes evocarla de nuevo como acción adicional.\n\nPuedes usar una acción para hacer un ataque de conjuro cuerpo a cuerpo con la hoja ardiente. Si impactas, el objetivo recibe 3d6 de daño de fuego.\n\nLa cimitarra emite luz brillante en un radio de 3 metros y luz tenue 3 metros más allá.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 4 o más, el daño aumenta en 1d6 por cada dos niveles por encima de 2 que tenga el espacio que hayas empleado.",
        mechanics = "Creas una haz ardiente como una cimitarra en una mano libre. Desaparece si lo sueltas, pero lo puedes evocar como acción adicional. Puedes realizar un ataque de conjuro cuerpo a cuerpo para infligir 3d6 puntos de daño por fuego. El daño aumenta 1d6 por cada dos niveles por encima",
