        mechanics = "Creas tres duplicados ilusorios de ti mismo. Se mueven a la vez que tu, imitan tus acciones y se cambian de posición. Tienen CA igual a 10 + tu mod. de Destreza y son destruidos con un impacto directo. Según los duplicados que queden, hay una posibilidad de que los ataques hacia",
