        description = "Mediante este conjuro consigues que un animal entregue un mensaje. Elige a una bestia Diminuta, como una ardilla, un arrendajo azul o un murciélago. Escoge una localización, que debes haber visitado, y un destinatario que corresponda a una descripción general, como \"un hombre o una mujer con el uniforme de la guardia de la ciudad\" o \"un enano pelirrojo con un sombrero puntiagudo\". Después, di al animal un mensaje de hasta veinticinco palabras. La bestia objetivo viaja hasta el final de la duración del conjuro hacia la localización elegida. Los animales son capaces de recorrer hasta 80,5 km en 24 horas si pueden volar y 40,2 km en caso contrario.\n\nCuando el mensajero llega, entrega tu mensaje a la criatura descrita, reproduciendo el sonido de tu voz. El animal solo hablará a una criatura que encaje con la descripción dada. Si el mensajero no alcanza su destino antes del final de la duración del conjuro, el mensaje se pierde y la bestia vuelve a donde lanzaste el conjuro.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 3 o más, la duración aumenta en 48 horas por cada nivel por encima de 2 que tenga el espacio que hayas empleado.",
