        description = "Eres capaz de cegar o ensordecer a un enemigo. Una criatura de tu elección que puedas ver dentro del alcance debe realizar una tirada de salvación de Constitución. Si falla, queda cegada o ensordecida, a tu elección, hasta el final de la duración del conjuro. Al final de cada uno de sus turnos, el objetivo puede hacer otra tirada de salvación de Constitución. Si tiene éxito, el efecto del conjuro termina para él.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 3 o mayor, puedes elegir como objetivo a una criatura adicional por cada nivel por encima de 2 que tenga el espacio que hayas empleado.",
        mechanics = "Una criatura que puedas ver dentro el alcance realiza una TS de Constitución. Si falla, queda cegado o ensordecido (según decidas). Al final de cada uno de sus turnos, puede reintentar la TS para anular el conjuro. Apunta a una criatura adicional por cada nivel por encima de 2.",
        roleNotes = "",
    },
    {
        id = "sugestion",
        name = "Sugestion",
        level = 2,
        school = "Encantamiento",
        affinity = "Arcano",
        classes = { "Brujo", "Mago", "Sacerdote", "Picaro Sutileza" },
        categories = { "Control", "Social" },
        castingTime = "1 accion",
        range = "9 metros",
        components = "V, M",
        duration = "Concentración, hasta 8 horas",
        concentration = false,
        concentration = true,
        ritual = false,
        savingThrow = "",
        attack = "",
        damage = "",
        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136446,
        description = "Influencias mágicamente a una criatura a la que puedas ver dentro del alcance y que pueda oírte y comprenderte. Sugieres al objetivo un curso de acción (limitado a una o dos frases), pero siempre expresado de tal forma que parezca razonable. Pedirle a la criatura que se apuñale, se empale en una lanza, se inmole o realice cualquier otra actividad claramente dañina termina el conjuro. Las criaturas que no puedan ser hechizadas no se ven afectadas por este con ju ro.\n\nEl objetivo debe hacer una tirada de salvación de Sabiduría. Si falla, llevará a cabo la acción que le sugieres hasta donde le permitan sus capacidades. Esta acción puede continuar hasta el final de la duración del conjuro. Si la sugerencia puede ser llevada a cabo en menos tiempo, el conjuro terminará cuando el objetivo complete la tarea encomendada.\n\nPuedes especificar que ciertas condiciones disparen una actividad especial mientras el conjuro siga activo. Por ejemplo, puedes sugerir a un caballero que entregue su caballo de guerra al primer mendigo que vea. Si la condición no se cumple antes de que termine el conjuro, entonces la actividad no se lleva a cabo.\n\nSi tú o cualquiera de tus compañeros dañáis al objetivo, el conjuro termina.",
        mechanics = "Sugieres mágicamente a una criatura un curso de acción que suene razonable. Si falla una TS de Sabiduría, lo seguira lo mejor que pueda. Puedes establecer una condicion que activara la tarea. El conjuro termina si tu o tus companeros danais al objetivo. No afecta a criaturas inmunes a ser hechizadas.",
        roleNotes = "",
    },
    {
        id = "telarana",
        condition = { id = "restrained" },  -- TS Destreza; restringido por la telarana, repite
