        concentration = false,
        concentration = true,
        ritual = false,
        savingThrow = "",
        attack = "",
        damage = "",
        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136447,
        description = "Conjuras una masa de telarañas densa y pegajosa en un punto de tu elección dentro del alcance. Las telarañas ocupan un cubo de 6,1 metros de lado desde ese punto y permanecerán allí hasta el final de la duración del conjuro. La zona cubierta se considera ligeramente oscura y terreno difícil.\n\nSi las telarañas no están ancladas entre dos objetos sólidos (como muros o árboles) o extendidas sobre un suelo, muro o techo, se colapsarán sobre sí mismas y el conjuro terminará al final de tu próximo turno. Las telarañas dispuestas sobre una superficie plana tienen una profundidad de 1,5 metros.\n\nCualquier criatura que comience su turno en las telarañas o que entre en ellas durante el mismo, debe hacer una tirada de salvación de Destreza. Si la falla, quedará apresada mientras siga en las telarañas *o* hasta que se libere. Una criatura apresada puede utilizar su acción para hacer una prueba de Fuerza contra tu CD de salvación de conjuro. Si la supera, dejará de estar apresada.\n\nLas telarañas son inflamables. Cualquier cubo de 1,5 metros de lado expuesto al fuego se quema por completo en\n\n1 asalto, causando 2d4 de daño de fuego a cualquier criatura que comience su turno en el incendio.",
        mechanics = "Creas una masa de telaranas pegajosas que llena un cubo de 6,1 metros. La zona se considera ligeramente oscura y terreno difícil. Cada criatura que empieza su turno en la telarana o que entra debe superar una TS de Destreza o quedar apresada. Para liberarse, debe superar una prueba de Fuerza.",
        roleNotes = "",
