        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136449,
        description = "Tocas un segmento de cuerda de hasta 18,3 metros de longitud.\n\nEsto hace que un extremo de la cuerda se alce hasta que toda la cuerda cuelgue de manera perpendicular al suelo. En el extremo superior de la cuerda se abre una entrada mágica a un espacio extradimensional que durará hasta el final del conjuro.\n\nEste espacio puede ser alcanzado subiendo por la cuerda hasta su final. En él caben hasta ocho criaturas de tamaño Mediano o más pequeñas. Se puede tirar de la cuerda para meterla en el espacio, lo que hace que desaparezca de la vista de aquellos en el exterior.\n\nLos ataques y conjuros no pueden cruzar esta entrada al espacio extradimensional en ningún sentido, pero los que están dentro podrán ver hacia fuera como si hubiera una ventana de 3 por 1,5 metros centrada en la cuerda.\n\nCualquier cosa dentro del espacio extradimensional cae al exterior cuando el conjuro termina.",
        mechanics = "Una cuerda que toques se alza en el aire y, en el extremo mas alto, se abre un portal invisible que lleva a un espacio extradimensional al que se accede trepando por la cuerda. Los ataques y conjuros no pueden atravesar el portal. Desde dentro se puede ver el exterior, pero no al reves.",
