        description = "Este conjuro protege a una criatura voluntaria a la que toques y crea una conexión mística entre vosotros hasta que el conjuro termine. Mientras el objetivo se encue ntre a 18,3 metros o menos de ti, obtiene un modificador de +1 a su CA y tiradas de salvación, así como resistencia a todo el daño. Sin embargo, cada vez que reciba daño. tú sufrirás la misma cantidad de daño.\n\nEl conjuro finaliza si llegas a tener O puntos de golpe o si el objetivo y tú os separáis más de 18,3 metros. También termina si se lanza otra vez sobre cualquiera de las dos criaturas conectadas o si utilizas una acción para finalizarlo.",
        mechanics = "Proteges a una criatura voluntaria con una conexion mistica. Mientras este a 18,3 metros o menos de ti, obtiene +1 a la CA y a las TS y es resistente a todos los danos. Cada vez que recibe daño, tu recibes la misma cantidad. Una criatura no puede tener dos vinculos custodios.",
