        icon = 136453,
        description = "Creas una zona mágica que protege contra el engaño. Sus dimensiones son las de una esfera de 4,6 metros de radio alrededor de un punto de tu elección dentro del alcance. Hasta el final del conjuro, cuando una criatura entre en la zona de la verdad por primera vez en un turno, o empiece su turno en ella, debe realizar una tirada de salvación de Carisma. Si fracasa, no podrá mentir mientras esté en la zona mágica. Sabrás si una criatura ha tenido éxito o ha fracasado en su tirada de salvación.\n\nCualquier criatura afectada es consciente del conjuro y, por tanto, puede evitar responder a preguntas a las que normalmente respondería con una mentira. Además, podrá ser evasiva en sus respuestas mientras se mantenga dentro de los límites de la verdad.",
        mechanics = "Creas una zona que te protege del engaño en una esfera de 4,6 metros. Al entrar o comenzar el turno en el área, toda criatura debe hacer una TS de Carisma. Si falla, no puede decir una mentira deliberadamente dentro del área. Tu sabes si ha acertado o fallado. La criatura es consciente del conjuro y puede evitar responder o ser evasiva dentro de los limites de la verdad.",
