        mechanics = "Salvación de Constitución al lanzar y al inicio de cada turno del lanzador. Fallo: 1d10 fuego. Éxito: mitad y termina. Al terminar explota: Destreza en radio de 3 metros, 2d6 fuego o mitad. A nivel superior: +1d6 a la explosión por nivel.",
        roleNotes = "Una llama interna que convierte al objetivo en una amenaza para quienes permanezcan cerca.",
