        mechanics = "Hasta tres criaturas voluntarias que puedas ver dentro del alcance consiguen obtienen la capacidad de moverse por cualquier superficie liquida como si fuera un terreno solido inofensivo. Si tu objetivo esta sumergido en un liquido, lo saca a la superficie a una velocidad de 60 pi",
