        description = "Convocas espíritus feéricos que toman la forma de bestias en espacios desocupados que puedas ver dentro del alcance. Elige una de las siguientes opciones para lo que convocas:\n\n• Una bestia con valor de desafío 2 o menos.\n• Dos bestias con valor de desafío 1 o menos.\n• Cuatro bestias con valor de desafío 1/2 o menos.\n• Ocho bestias con valor de desafío 1/4 o menos.\n\nCada bestia se considera feérica y desaparece cuando sus puntos de golpe se reducen a 0 o el conjuro termina.\n\nLas bestias convocadas son amistosas hacia ti y tus compañeros. Las criaturas actúan como un grupo con sus propios turnos, con una sola de tirada de iniciativa común. Obedecen cualquier mandato verbal tuyo (no requiere acción). Si no les das ninguna orden, se defenderán de criaturas hostiles, pero no realizarán ninguna otra acción.\n\nEl DM tiene el perfil de las criaturas. ***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de determinados niveles superiores, el número de criaturas de la opción elegida aumenta: el doble si usas un espacio de conjuro de nivel 5, el triple si es de nivel 7 y cuatro veces más si es de nivel 9.",
        mechanics = "Convocas espíritus feericos en forma de bestia con un valor de desafío total de 2 o menos. Desaparecen cuando sus PG llegan a 0 o cuando el conjuro termina. Son amistosas y obedecen tus órdenes. La cantidad de bestias aumenta según el nivel de conjuro: x2 a nivel 5, x3 a nivel 7",
