        source = "Reglas basicas",
        icon = 136517,
        description = "Cuando lanzas este conjuro inscribes un glifo que liberará posteriormente un efecto mágico. Puedes hacerlo en una superficie (como una mesa o una sección de un muro o suelo) o dentro de un objeto que pueda cerrarse (como un libro, pergamino o cofre del tesoro), para así esconder el glifo. Este puede cubrir una zona de hasta 3 metros de diámetro. Si la superficie o el objeto es alejado más de 3 metros del punto donde lanzaste el conjuro, este termina sin activarse y el glifo queda roto.\n\nEl glifo es casi invisible y es necesario tener éxito en una prueba de Inteligencia (Investigación) con CD igual a tu salvación de conjuros para encontrarlo. Decides qué activa el glifo cuando lanzas el conjuro. Para glifos inscritos en una superficie, las activaciones más típicas incluyen tocar o pisar el glifo, retirar un objeto que lo cubría, acercarse a una cierta distancia del glifo o manipular el objeto donde está inscrito. Para glifos inscritos en un objeto, las activaciones más comunes incluyen abrir el objeto, acercarse a una cierta distancia de él, o ver o leer el glifo. Una vez que este es activado, el conjuro termina.\n\nPuedes precisar aún más las condiciones de activación, para que el conjuro solo se active bajo ciertas circunstancias o de acuerdo a unas características físicas concretas (como la altura o el peso), tipo de criatura (por ejemplo, que únicamente afecte a aberraciones o drows) o alineamiento. También puedes crear ciertas condiciones para que algunas criaturas no activen el glifo, como diciendo una palabra clave.\n\nCuando inscribas el glifo, elige entre runas explosivas o glifo de conjuro.\n\n***Runas explosivas.*** Cuando se activa, el glifo estalla con energía mágica en una esfera de 6,1 metros de radio alrededor del mismo. La esfera se extiende más allá de las esquinas. Todas las criaturas en el área deben hacer una tirada de salvación de Destreza. Cada criatura recibe 5d8 de daño de ácido, frío, fuego, relámpago o trueno (a tu elección al crear el glifo) si falla la tirada o la mitad si la supera.\n\n***Glifo de conjuro.*** Puedes guardar un conjuro preparado de nivel 3 o menos en el glifo, lanzándolo como parte de la creación de este. El conjuro debe elegir como objetivo a una sola persona o una zona y no tiene efecto en el momento de lanzarlo, sino que, cuando se activa el glifo, se lanza el conjuro guardado. Si el conjuro tiene un objetivo, este será la criatura que activó el glifo. Si el conjuro afecta a una zona, la zona queda centrada en la criatura. Si el conjuro convoca criaturas hostiles o crear objetos o trampas dañinos, estos aparecen lo más cerca posible del intruso y lo atacan. Si el conjuro requiere concentración, dura hasta el final de su duración completa.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 4 o más, el daño de las runas explosivas aumenta en 1d8 por cada nivel por encima de 3 que tenga el espacio que hayas empleado. Si creas un *glifo de conjuro,* puedes guardar un conjuro cuyo nivel sea igual o inferior al nivel del espacio de conjuro que hayas utilizado para lanzar *glifo custodio.*",
        mechanics = "Crea una trampa mágica sobre un objeto o zona de hasta 3 metros de diametro. Indica la condicion de activacion. Puede almacenar un conjuro de nivel igual o inferior al espacio de conjuro utilizado o provocar una explosión de 6,1 metros de radio que causa 5d8 (+1d8 por nivel de conjur",
        roleNotes = "",
    },
    {
        id = "hablar_con_las_plantas",
        name = "Hablar con las plantas",
        level = 3,
        school = "Transmutacion",
        affinity = "Naturaleza",
        classes = { "Druida" },
        categories = { "Comunicacion", "Social" },
        castingTime = "1 accion",
        range = "Personal (Cilindro de 9 metros)",
        components = "V, S",
        duration = "10 minutos",
        concentration = false,
        ritual = false,
        savingThrow = "",
        attack = "",
        damage = "",
        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136518,
        description = "Imbuyes todas las plantas a 9,1 metros o menos de ti con vivacidad y una conciencia limitada, permitiéndoles comunicarse contigo y seguir órdenes simples. Puedes preguntar a las plantas sobre eventos que han ocurrido en el área del conjuro en el último día, como por ejemplo las criaturas que han pasado por allí, el clima u otras circunstancias.\n\nSi dentro del alcance hay terreno que es difícil a causa de la vegetación (como matorrales o sotobosque), puedes convertirlo en terreno ordinario hasta el final del conjuro. Alternativamente, puedes convertir en terreno difícil una zona de terreno ordinario que tenga plantas para, por ejemplo hacer que tus perseguidores sean entorpecidos por enredaderas y ramas bajas.\n\nLas plantas también pueden ser capaces de llevar a cabo otras tareas, a discreción del DM. Este conjuro no permite que se desarraiguen y se desplacen, pero podrán mover libremente sus ramas, zarcillos y tallos.\n\nSi una criatura planta está en el área, puedes comunicarte con ella si compartís un idioma común, pero no consigues ninguna forma mágica de influenciarla.\n\nEste conjuro puede hacer que las plantas creadas por el conjuro *enmarañar* suelten a una criatura apresada.",
        mechanics = "Imbuyes las plantas a 9,1 metros o menos de ti con conciencia y animacion limitadas, lo que les da la capacidad de comunicarse contigo y seguir órdenes sencillas. Puedes preguntarles sobre eventos de los ultimos dias, convertir terreno difícil en fácil o viceversa, liberar una criat",
        roleNotes = "",
    },
    {
        id = "hablar_con_los_muertos",
        name = "Hablar con los muertos",
        level = 3,
        school = "Nigromancia",
        affinity = "Sombra",
        classes = { "Brujo", "Caballero de la Muerte", "Sacerdote" },
