        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136519,
        description = "Otorgas una sombra de vida e inteligencia a un cadáver de tu elección que se encuentre dentro del alcance, permitiéndole contestar a tus preguntas. El cadáver debe conservar su boca y no ser un muerto viviente. El conjuro fallará si este cadáver ha sido objetivo del mismo conjuro en los últimos 10 días.\n\nPuedes hacer hasta cinco preguntas antes del final del conjuro. El cadáver solo poseerá los mismos conocimientos que en vida, incluyendo idiomas. Las respuestas suelen ser breves, crípticas o repetitivas, y el cadáver no tiene obligación de proporcionarte una respuesta veraz si es hostil hacia ti o te reconoce como enemigo. Este conjuro no devuelve el alma de una criatura a la vida, solo el espíritu que la anima. Por tanto, el cadáver no puede adquirir nueva información, entender nada que haya ocurrido desde que murió o especular sobre eventos futuros.",
        mechanics = "Concedes la apariencia de vida e inteligencia a un cadaver, lo que le permite responder a hasta 5 preguntas que le hagas. Debe tener boca aun y no ser un no muerto. Solo sabe lo que sabia en vida. Las respuestas suelen ser breves, cripticas o repetitivas. Puede no responder a hos",
        roleNotes = "",
    },
    {
        id = "imagen_mayor",
        name = "Imagen mayor",
        level = 3,
        school = "Ilusion",
        affinity = "Arcano",
        classes = { "Brujo", "Mago" },
        categories = { "Control" },
        castingTime = "1 accion",
