        concentration = false,
        concentration = true,
        ritual = false,
        savingThrow = "",
        attack = "",
        damage = "",
        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136520,
        description = "Creas una imagen de un objeto, una criatura u otro tipo de fenómeno visible, cuyas dimensiones no excedan las de un cubo de 6,1 metros de lado. La imagen aparece en un sitio que puedas ver dentro del alcance y se mantiene hasta el final de la duración del conjuro. Parece completamente real, incluyendo sonidos, olores y temperatura apropiados a lo que se representa. No puedes crear suficiente calor o frío para hacer daño, sonido lo suficientemente fuerte como para hacer daño de trueno o ensordecer a una criatura, o un olor que pudiera causar náuseas a una criatura (como el hedor de un troglodita).\n\nMientras estés dentro del alcance de la ilusión, puedes utilizar tu acción para moverla a otro sitio dentro de dicho alcance. Al cambiarla de sitio, puedes alterar su apariencia de forma que sus movimientos parezcan naturales. Por ejemplo, si creas la imagen de una criatura y la mueves, puedas alterarla de forma que parezca estar andando. De forma similar, puedes hacer que la ilusión produzca distintos sonidos en diferentes momentos, incluso mantener una conversación, por ejemplo.\n\nLa interacción física con la imagen revela que es una ilusión, ya que las cosas la atraviesan. Si una criatura emplea su acción para examinar la imagen, puede determinar que es una ilusión si tiene éxito en una prueba de Inteligencia (Investigación) cuya CD es tu salvación de conjuros. Si la criatura descubre que la imagen es una ilusión, podrá ver a través de ella y sus otras cualidades sensoriales se vuelven tenues para esta criatura.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 6 o más, el conjuro se mantiene hasta que sea disipado, sin requerir concentración.",
        mechanics = "Creas la imagen de un objeto, criatura y algun otro fenomeno visible de hasta 6,1 metros. La imagen parece real, incluyendo sonidos, olores y temperatura correspondiente a lo que representa. Puedes moverla como una acción. Se puede distinguir la ilusion con una prueba de Inteligenc",
        roleNotes = "",
    },
