        damage = "",
        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136521,
        description = "Tocas a una criatura, que debe superar una tirada de salvación de Sabiduría o quedar maldita hasta el final de la duración del conjuro. Cuando lanzas este conjuro, elige la naturaleza de la maldición de entre las siguientes opciones:\n\n• Elige una puntuación de característica. Mientras está maldito, el objetivo tiene desventaja en las pruebas de característica y tiradas de salvación de dicha característica.\n• Hasta el final de la duración del conjuro, el objetivo sufre desventaja en sus tiradas de ataque contra ti.\n• Mientras siga maldito, el objetivo debe realizar una tirada de salvación de Sabiduría al principio de cada turno. Si fracasa, gastas o acción de ese turno en no hacer nada.\n• Mientras el objetivo siga maldito, tus ataques y conjuros le hacen 1d8 puntos extra de daño necrótico adicional.\n\nEl conjuro *levantar maldición* termina estos efectos. Bajo la discreción del DM, puedes elegir un efecto alternativo para la maldición, pero no deberla ser más poderoso que los descritos más arriba. El DM tiene la última palabra sobre los efectos de una maldición.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 4 o más, la duración pasa a ser: concentración, hasta 10 minutos. Si utilizas un espacio de conjuro de nivel 5 o más, la duración es de 8 horas. Si usas un espacio de conjuro de nivel 7 o 8, la duración es de 24 horas. Si empleas un espacio de conjuro de nivel 9, el conjuro dura hasta que sea disipado. Además, al lanzar este conjuro con un espacio de nivel 5 o más, no es necesaria la concentración para mantener la duración especificada más arriba.",
        mechanics = "Si no supera una TS de Sabiduría, elige que la criatura tocada tenga: desventaja en pruebas y TS de una característica; desventaja en los ataques contra ti; superar una TS de Sab o no actuar en su acción; tus ataques infligen 1d8 necrótico. Utilizar conjuro de nivel superior aume",
        roleNotes = "",
