        description = "Aparece una nube tormentosa en forma de cilindro, de\n\n3 metros de altura y 18,3 metros de radio, centrada en un punto que puedas ver a 30,5 metros directamente encima de ti. El conjuro falla si no puedes contemplar un punto en el aire donde pueda aparecer la nube (por ejemplo, si estás en una habitación donde no quepa).\n\nCuando lances el conjuro, elige un punto que puedas ver dentro del alcance. Un relámpago cae desde la nube a ese punto. Cada criatura a 1,5 metros o menos debe hacer una tirada de salvación de Destreza. Sufrirán 3d10 de daño de relámpago si fallan la tirada o la mitad del daño si la superan. En cada uno de tus turnos hasta el final del conjuro puedes usar tu acción para llamar al relámpago de esta manera, en el mismo punto o en otro distinto.\n\nSi cuando lanzas este conjuro estás al aire libre y hay tormenta, el conjuro te da el control de esta en vez de crear una nueva. En estas condiciones, el daño del conjuro aumenta en 1d10.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 4 o más, el daño aumenta en 1d10 por cada nivel por encima de 3 que tenga el espacio que hayas empleado.",
        mechanics = "Creas una nube de tormenta de 18,3 metros de radio. Al lanzar el conjuro y como acción en los turnos siguientes, un relámpago cae donde elijas. Las criaturas a 1,5 metros o menos deben superar una TS de Destreza o recibir 3d10 de relámpago (mas 1d10 por cada nivel por encima de 3). Si ti",
