        description = "Una estrella de energía divina avanza en una línea de 9 metros de largo y 1,5 metros de ancho desde ti en una dirección de tu elección. Cada criatura aliada en el camino de la estrella recupera 2d8 puntos de golpe, y cada criatura hostil debe hacer una tirada de salvación de Destreza, recibiendo 3d8 de daño radiante si falla o la mitad si tiene éxito.\n\nA niveles superiores. Cuando lanzas este hechizo con un espacio de nivel 4 o superior, la curación y el daño del hechizo aumentan en 1d8 por cada nivel de espacio de conjuro por encima del 3.",
        mechanics = "Línea de 9 metros por 1,5 metros. Aliados: curan 2d8. Hostiles: salvación de Destreza; fallo 3d8 radiante, éxito mitad. A nivel superior: +1d8 curación y daño por nivel.",
