        sourceGroup = "Warcraft Custom",
        source = "Warcraft 5E Custom",
        icon = 136545,
        description = "Extraes poder arcano fluctuante y lo liberas en una onda de energía. Cada criatura en el área debe hacer una tirada de salvación de Destreza. Con una salvación fallida, el objetivo sufre 6d8 de daño de fuerza y no puede tomar reacciones hasta el inicio de su próximo turno. Si tiene éxito, el objetivo recibe la mitad de daño y puede usar sus reacciones normalmente.\n\nA niveles superiores. Cuando lanzas este hechizo con un espacio de conjuro de nivel 4 o superior, el daño aumenta en 1d8 por cada nivel de espacio de conjuro por encima del\n\nHorda Tambaleante Horda Tambaleante *Horda Gargantuesca de no muertos Medianos, maligna caótica*\n\n**Clase de Armadura** 8 **Puntos de Golpe** 145 (10d20 + 40) **Velocidad** 6 m.\n\n**FUE DES CON INT SAB CAR**\n\n25 (+7) 6 (-2) 18 (+4) 3 (-4) 6 (-2) 5 (-3)\n\n**Tiradas de Salvación** Sab +2 **Inmunidad al Daño** veneno **Inmunidad a Condiciones** cegado, encantado, ensordecido, agotado, asustado, apresado, incapacitado, paralizado, petrificado, envenenado, boca abajo, restringido, aturdido, inconsciente **Sentidos** visión en la oscuridad 18 m., percepción pasiva\n\n**Idiomas** — **Desafío** 8 (3,900 PX)\n\n***Compulsión Devoradora.*** La horda puede compartir el espacio con otra criatura. Si una criatura que no sea un no muerto o constructo comparte el espacio con la horda al inicio del turno de esta, la horda queda incapacitada (ignorando su inmunidad a esta condición) y la criatura queda engullida. Mientras está engullida, la criatura está restringida y recibe 21 (6d6) de daño perforante al inicio de cada turno de la horda, o 10 (3d6) si la horda tiene la mitad o menos de sus puntos de golpe. La criatura debe superar una salvación de Constitución CD 15 o infectarse con la enfermedad de la muerte tambaleante.",
        mechanics = "Esfera de 3 metros centrada en ti. Salvación de Destreza. Fallo: 6d8 fuerza y sin reacciones hasta el inicio del próximo turno. Éxito: mitad y conserva reacciones. A nivel superior: +1d8 por nivel.",
