        description = "Una luz fría emana de tu mano al cielo mientras fragmentos azules caen en un cilindro de 6 metros de radio y 12 metros de altura centrado en un punto dentro del alcance. Hasta que el hechizo termine, fragmentos de hielo caen sobre la zona. Cuando una criatura entra en el área por primera vez en un turno o comienza su turno allí, debe hacer una tirada de salvación de Destreza. Si falla, recibe 3d6 de daño por frío o la mitad si tiene éxito. A niveles superiores. Cuando lanzas este hechizo con un espacio de nivel 4 o superior, el daño aumenta en 1d6 por cada nivel de espacio de conjuro por encima del 3.",
        mechanics = "Área: cilindro de 6 metros de radio y 12 metros de altura. Salvación de Destreza al entrar por primera vez en un turno o empezar turno dentro. Fallo: 3d6 frío. Éxito: mitad. A nivel superior: +1d6 por nivel.",
        roleNotes = "Una tormenta helada sostenida que bloquea terreno y desgasta a quienes permanezcan dentro.",
