        source = "Warcraft 5E Custom",
        icon = 136601,
        description = "Manipulas el flujo de maná que recorre a una criatura. Si la criatura no es voluntaria, debes superar antes un ataque de conjuro cuerpo a cuerpo. Al tocarla, eliges qué efecto le aplicas durante la duración del conjuro.\nAmpliar. Amplificas su poder mágico: la criatura recibe daño adicional cuando la golpea un conjuro, inflige daño adicional al lanzar conjuros y restaura puntos de golpe adicionales con sus conjuros, todo en una cantidad igual a tu modificador de lanzamiento de conjuros.\nDisminuir. Atenúas su poder mágico: la criatura reduce el daño que recibe de conjuros, el daño que inflige con ellos y los puntos de golpe que un conjuro le restaura, en una cantidad igual a tu modificador de lanzamiento de conjuros.",
        mechanics = "El objetivo debe superar una salvación de Constitución si no es voluntario. Si falla, eliges ampliar o disminuir el efecto: ampliar aumenta en 1 dado el daño o curación de un hechizo, o aumenta 3 metros un área o alcance relevante; disminuir reduce en 1 dado el daño o curación, o reduce 3 metros un área o alcance relevante. El DM decide el ajuste equivalente para efectos sin dados.",
        roleNotes = "Un mago experto no solo lanza magia: también tira de sus hilos y cambia su intensidad.",
