        icon = 136602,
        description = "Manipulas las sombras a tu alrededor, enviando apariciones para acosar a tu enemigo. Creas tres apariciones sombrías de tamaño mediano en espacios desocupados a 3 metros de ti. Elige un objetivo dentro del alcance para cada aparición. Cada aparición puede tener el mismo o diferente objetivo. Al final de cada uno de tus turnos, tus apariciones se mueven 6 metros hacia su objetivo, atravesando criaturas y obstáculos, e ignorando terreno difícil.\n\nCuando una aparición está en el mismo espacio que otra criatura, explota, obligando a esa criatura a hacer una tirada de salvación de Inteligencia. Si falla, recibe 8d6 de daño psíquico o la mitad si tiene éxito. Una criatura que falle esta tirada de salvación también ve su velocidad de movimiento reducida a 0 hasta el inicio de su próximo turno.\n\nDespués de perder la concentración en este hechizo, todas las apariciones presentes duran 1 asalto.\n\nA niveles superiores. Cuando lanzas este hechizo con un espacio de nivel 5 o superior, las apariciones infligen 1d6 de daño psíquico adicional por cada nivel de espacio de conjuro por encima del 4.",
        mechanics = "Cuando una aparicion esta en el mismo espacio que otra criatura, explota y la criatura hace salvación de Inteligencia. Fallo: 8d6 psíquico y velocidad 0 hasta el inicio de su próximo turno. Éxito: mitad de daño. Tras perder concentración, las apariciones existentes duran 1 asalto. A nivel superior: +1d6 psíquico por nivel por encima del 4.",
        roleNotes = "Sombras con voluntad propia cruzan el campo hasta estallar contra la mente del enemigo.",
