        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136610,
        description = "Este conjuro ataca y retuerce la mente, creando ilusiones y provocando acciones incontroladas. Cada criatura en una esfera de 3 metros de radio centrada en un punto de tu elección dentro del alcance debe tener éxito en una tirada de salvación de Sabiduría o será afectada por el conjuro.\n\nUna criatura afectada no puede llevar a cabo reacciones y debe tirar 1d10 al principio de cada uno de sus turnos para determinar cómo se comporta ese turno:\n\n**dlO Comportamiento**\n\nLa criatura emplea todo su movimiento en avanzar en una dirección aleatoria. Para determinar la dirección, lanza 1d8 asignando una dirección a cada cara del dado. La criatura no realiza acciones este turno.\n\n2-6 La criatura no se mueve o realiza acciones este turno.\n\n7-8 La criatura usa su acción para hacer un ataque cuerpo a cuerpo contra una criatura determinada aleatoriamente dentro de su alcance. Si no hay ninguna criatura dentro del alcance, no hace nada este turno.\n\n9-1 O La criatura puede actuar y moverse con normalidad.\n\nAl final de cada uno de sus turnos, el objetivo puede realizar otra tirada de salvación de Sabiduría; si tiene éxito, el conjuro termina para él.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 5 o más, el radio de la esfera aumenta en 1,5 metros por cada nivel por encima de 4 que tenga el espacio que hayas empleado.",
