        description = "Convocas criaturas feéricas en espacios desocupados que puedas ver dentro del alcance. Elige una de las siguientes opciones para lo que convocas:\n\n• Un feérico con valor de desafío 2 o menos.\n• Dos feéricos con valor de desafío 1 o menos.\n• Cuatro feéricos con valor de desafío 1/2 o menos.\n• Ocho feéricos con valor de desafío 1/4 o menos.\n\nUna criatura invocada desaparece si sus puntos de golpe se reducen a 0 o el conjuro termina.\n\nLas criaturas invocadas son amistosas hacia ti y tus compañeros. Las criaturas actúan como un grupo con sus propios turnos, con una sola de tirada de iniciativa común. Obedecen cualquier mandato verbal tuyo (no requiere acción). Si no les das ninguna orden, se defenderán de criaturas hostiles, pero no realizarán ninguna otra acción.\n\nEl DM tiene el perfil de las criaturas. ***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de determinados niveles superiores, el número de criaturas de la opción elegida aumenta: el doble si usas un espacio de conjuro de nivel 6 y el triple si es de nivel 8.",
        mechanics = "Invocas criaturas feericas apropiadas al nivel del conjuro. Actuan en su propia iniciativa, son amistosas hacia ti y obedecen tus órdenes verbales. El DM decide estadisticas exactas según la opcion elegida.",
