        icon = 136613,
        description = "Invocas a un poderoso no muerto desde las criptas o mataderos de Rasganorte. Eliges el tipo de no muerto, que debe tener un nivel de desafío 5 o menor, como un revenant o espectro. Aparece en un espacio desocupado que puedas ver dentro del alcance y desaparece cuando sus puntos de golpe lleguen a 0 o el hechizo termine.",
        mechanics = "Tira iniciativa para el no muerto, que tiene sus propios turnos. Al invocarlo y en cada uno de tus turnos puedes darle una orden verbal sin acción para que actue en su próximo turno. Si no das órdenes, ataca a cualquier criatura que lo haya atacado. Si pierdes concentración, ataca al ser vivo mas cercano. A nivel superior: +1 al nivel de desafío por nivel por encima del 4.",
        roleNotes = "El caballero de la muerte llama a un servidor de Rasganorte y lo ata a su voluntad.",
    },
    {
        id = "controlar_agua",
        name = "Controlar agua",
        level = 4,
        school = "Transmutacion",
        affinity = "Naturaleza",
        classes = { "Chaman" },
        categories = { "Control" },
        castingTime = "1 accion",
        range = "90 metros",
        components = "V, S, M",
        duration = "Concentracion, hasta 10 minutos",
        concentration = true,
        ritual = false,
        savingThrow = "",
        attack = "Control de area",
        damage = "",
        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136614,
        description = "Hasta el final de la duración del conjuro, controlas cualquier masa de agua que no esté en movimiento dentro de un área de tu elección con forma de cubo de hasta 30,5 metros de lado. Cuando lanzas este conjuro, elige uno de los siguientes efectos. Como una acción, en tu turno, puedes repetir el mismo efecto o elegir uno nuevo.\n\n***Inundación.*** Haces que el nivel de toda el agua estancada en al área suba hasta 6,1 metros. Si esta área incluye una orilla, el agua inunda la tierra seca circundante.\n\nSi eliges un área en una masa de agua, en vez de eso creas una ola de 6,1 metros de altura que viaja de un lado de la masa de agua al otro y después rompe. Cualquier vehículo de tamaño Enorme o menor en el camino de la ola es transportado al otro lado. Además, tiene un 25 % de posibilidades de volcar.\n\nEl nivel del agua se mantiene elevado hasta que termine el conjuro o elijas un efecto diferente. Si este efecto ha creado una ola, esta se repite al principio de tu próximo turno mientras el efecto de la inundación permanezca.\n\n***Abrir las aguas.*** Haces que el agua del área se aparte, creando una zanja. Se extiende a lo largo del área del conjuro, con el agua separada formando un muro a cada lado.\n\nLa zanja permanece hasta que el conjuro termine o elijas un efecto diferente. En ese caso, el agua llena lentamente la zanja durante el transcurso del siguiente asalto hasta que el nivel normal del agua se haya restablecido.\n\n***Redirigir caudal.*** Obligas a un flujo de agua corriente en el área a moverse en la dirección de tu elección, incluso si tiene que fluir a través de obstáculos, escalar muros o tomar otras direcciones improbables. El agua del área se mueve según indiques, pero una vez que salga del área del conjuro vuelve a fluir de forma natural, de acuerdo a las condiciones del terreno. El agua continúa moviéndose en la dirección de tu elección hasta que el conjuro termine o elijas un efecto diferente.\n\n***Remolino.*** Este efecto necesita que la masa de agua sea de, al menos, 15,2 metros cuadrados y tenga 7,6 metros de profundidad. Creas un remolino en el centro del área. Esto produce un vórtice de 1,5 metros de ancho en la base, hasta 15,2 metros de ancho en la parte más alta y hasta 7,6 metros de profundidad. Cualquier objeto o criatura en el agua y a 7,6 metros o menos del remolino se ve atraída 3 metros hacia él. Una criatura puede alejarse nadando del vórtice mediante una prueba de Fuerza (Atletismo) con CD igual a tu salvación de conjuros.\n\nCuando una criatura entra en el área del remolino por primera vez en un turno, o cuando empieza su turno en ella, debe realizar una tirada de salvación de Fuerza. Si fracasa, la criatura recibe 2d8 de daño contundente y queda atrapada en el vórtice hasta que el conjuro termine. Si la supera, recibe la mitad del daño y no queda atrapada. Una criatura atrapada en el remolino puede usar su acción para intentar alejarse de él de la manera descrita más arriba, pero tiene desventaja en la prueba de Fuerza (Atletismo) necesaria. La primera vez que un objeto entre en el vórtice cada turno recibe 2d8 de daño contundente. Este daño ocurre cada asalto que permanezca dentro.",
        mechanics = "Puedes inundar, dividir aguas, redirigir corriente o crear un remolino. Cada efecto modifica el terreno acuatico y puede arrastrar, abrir paso o dificultar el movimiento según la escena.",
        roleNotes = "Rios, estanques y mareas se inclinan ante tu gesto.",
    },
