        ritual = false,
        savingThrow = "Sabiduria",
        attack = "Salvacion",
        damage = "",
        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136617,
        description = "Intentas encantar a una bestia que puedas ver dentro del alcance. La criatura debe superar una tirada de salvación de Sabiduría o quedará hechizada por ti hasta el final de la duración del conjuro. Tiene ventaja en esta tirada de salvación si tú o alguna criatura amistosa hacia ti estáis luchando contra ella.\n\nMientras la bestia está hechizada, posees un enlace telepático con ella siempre y cuando ambos os halléis en el mismo plano de existencia. Puedes usar este enlace para enviar órdenes a la criatura mientras estés consciente (no requiere acción) y esta hará todo lo que está en su poder para obedecer. Puedes especificar un procedimiento simple, como \"ataca a esa criatura\", \"corre hasta allí\" o \"tráeme ese objeto\". Si la criatura cumple su orden y no recibe más mandatos de ti, se defiende y protege en la medida de sus posibilidades.\n\nPuedes utilizar tu acción para tomar un control total y preciso de la bestia. Hasta el final de tu próximo turno, la criatura solo realizará las acciones que elijas y no hará nada que no le permitas. Durante este tiempo también podrás hacer que la bestia lleve a cabo reacciones, pero eso hará que emplees también tu propia reacción.\n\nCada vez que recibe daño, la criatura hace una nueva tirada de salvación contra el conjuro. Si tiene éxito, el efecto del conjuro termina.\n\n***A niveles superiores.*** Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 5, la duración pasa a ser: concentración, hasta 10 minutos. Si usas un espacio de conjuro de nivel 6, la duración pasa a ser: concentración, hasta 1 hora. Si empleas un espacio de conjuro de nivel 7 o más, la duración pasa a ser: concentración, hasta 8 horas.",
        mechanics = "Salvación de Sabiduría. Fallo: la bestia queda hechizada y obedece órdenes mientras mantienes concentración.",
        roleNotes = "La voluntad de la bestia queda sujeta por magia primal.",
    },
    {
