        description = "Intentas hechizar a un humanoide que puedes ver dentro del alcance. El objetivo debe hacer una tirada de salvación Sabiduría, y lo hace con ventaja si tu o tus compañeros luchan contra el. Si falla la tirada de salvación, queda hechizado por ti hasta el fin del conjuro, o hasta que tu o tus compañeros le hagan daño. La criatura encantada es amigable contigo. Cuando el conjuro termina, la criatura sabe que fue encantada por ti.\n\nA niveles superiores. Cuando lances este conjuro usando un espacio de conjuro de nivel 5 o superior, puedes afectar una criatura adicional para cada nivel de espacio de conjuro por encima de 4°. Las criaturas deben estar dentro de 9,1 metros de cada una cuando les señalas.",
