        sourceGroup = "DnD",
        source = "DnD",
        icon = 136620,
        description = "Invocas un espíritu que asume la forma de un corcel leal y majestuoso. Apareciendo en un espacio desocupado dentro del alcance, el espíritu toma la forma que elijas: un grifo, un pegaso, un peryton, un lobo terrible, un rinoceronte o un tigre dientes de sable. La criatura tiene el perfil proporcionado en el Manual de Monstruos para la forma elegida, aunque es un celestial, feérico o infernal (tu elección) en lugar de su tipo de criatura normal. Además, si tiene una puntuación de Inteligencia de 5 o inferior, su Inteligencia se convierte en 6, y obtiene la capacidad de entender un idioma que hables.\n\nTú controlas al corcel en combate. Mientras que la montura está a 1,6 km de ti, puedes comunicarte telepáticamente con ella. Mientras estás montado, puedes hacer que cualquier conjuro que lances que solo te tenga como objetivo también afecte al corcel. El corcel desaparece temporalmente cuando cae a 0 puntos de golpe o cuando lo descartas como una acción. Si vuelves a lanzar este conjuro, se vuelve a invocar el corcel vinculado, con todos sus puntos de golpe restaurados y cualquier condición eliminada.\n\nNo puedes tener más de una montura vinculada por este conjuro o hallar corcel al mismo tiempo. Como acción, puedes liberar una montura de su vínculo, haciendo que desaparezca permanentemente.\n\nCada vez que el corcel desaparece, deja atrás cualquier objeto que llevaba o cargaba.",
        mechanics = "El corcel aparece en un espacio libre y actua como montura inteligente y aliada. Puede adoptar formas apropiadas como grifo, pegaso, rinoceronte, tigre dientes de sable u otra permitida por el DM.",
        roleNotes = "Una montura digna de leyenda responde a la llamada.",
