        sourceGroup = "DnD",
        source = "DnD",
        icon = 136624,
        description = "Conjuras una esfera de agua con un radio de 1,5 metros en un punto que puedes ver dentro del alcance. La esfera puede flotar, pero no más de 3 metros del suelo. La esfera permanece hasta el final de la duración del conjuro.\n\nCualquier criatura en el espacio de la esfera debe hacer una tirada de salvación de Fuerza. En una salvación exitosa, una criatura es expulsada de ese espacio al espacio no ocupado más cercano de la elección de la criatura fuera de la esfera. Una criatura enorme o más grande tiene éxito en la tirada de salvación automáticamente, y una criatura grande o más pequeña puede elegir fallarla. En una salvación fallida, una criatura queda apresada por la esfera y es engullida por el agua. Al final de cada uno de sus turnos, un objetivo apresado puede repetir la tirada de salvación, terminando el efecto sobre sí mismo en un éxito.\n\nLa esfera puede contener hasta cuatro criaturas medianas o más pequeñas o una criatura grande. Si la esfera apresa a una criatura que hace que supere esta capacidad, una criatura aleatoria que ya estaba apresada por la esfera se cae de ella y cae derribada en un espacio a 1,5 metros de ella.\n\nComo acción, puedes mover la esfera hasta 9,1 metros en línea recta. Si se mueve sobre un foso, un acantilado u otra caída, desciende de manera segura hasta que está flotando a 3 metros sobre el suelo. Cualquier criatura apresada por la esfera se mueve con ella. Puedes embestir criaturas con la esfera, obligándolas a realizar la tirada de salvación.\n\nCuando termina el conjuro, la esfera cae al suelo y apaga todas las llamas normales a 9,1 metros de distancia. Cualquier criatura apresada por la esfera es derribada en el espacio donde cae. El agua se desvanece.",
        mechanics = "Criaturas en el área hacen salvación de Fuerza. Si fallan quedan apresadas por la esfera. Puedes mover la esfera y arrastrar con ella a las criaturas atrapadas; estas pueden repetir la salvación para escapar.",
