        sourceGroup = "DnD",
        source = "DnD",
        icon = 136625,
        description = "Una esfera de 6,1 metros de radio de aire giratorio nace, centrada en un punto que elijas dentro del alcance. La esfera permanece hasta el final de la duración del conjuro. Cada criatura en la esfera cuando aparece o que termina su turno allí debe tener éxito en una tirada de salvación de Fuerza o recibir 2d6 de daño contundente. El espacio dentro de la esfera es considerado terreno difícil.\n\nHasta que termine el conjuro, puedes usar una acción adicional en cada uno de tus turnos para hacer que un rayo salte desde el centro de la esfera hacia una criatura que elijas hasta a 18,3 metros del centro. Realiza un ataque de conjuro a distancia. Tienes ventaja en la tirada de ataque si el objetivo está en la esfera. En un golpe, el objetivo recibe 4d6 de daño de relámpago. Las criaturas a menos de 9,1 metros de la esfera tienen desventajas en las pruebas de Sabiduría (Percepción) hechas para escuchar.\n\nA niveles superiores. Cuando lanzas este conjuro usando un espacio de conjuro de 5° nivel o superior, el daño para cada uno de sus efectos aumenta en 1d6 por cada nivel de espacio de conjuro por encima del 4º.",
        mechanics = "Al aparecer, criaturas en el área hacen salvación de Fuerza o reciben 2d6 contundente. El área es terreno difícil. Como acción adicional puedes lanzar un relámpago desde la esfera: ataque de conjuro a distancia, 4d6 relámpago.",
        roleNotes = "Un núcleo de tormenta ruge y escupe rayos.",
    },
    {
