        damage = "",
        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 136626,
        description = "Una esfera de fuerza destellante encierra a una criatura u objeto de tamaño Grande o menor dentro del alcance. Una criatura no voluntaria puede hacer una tirada de salvación de Destreza. Si falla, quedará encerrada hasta el final de la duración del conjuro.\n\nNada (ni objetos físicos, energía u otros efectos de conjuro) puede atravesar la barrera, hacia dentro o hacia fuera, pero una criatura que esté dentro de la esfera puede respirar con normalidad. La esfera es inmune a todo el daño. Además, una criatura u objeto albergada en su interior no puede ser dañado por ataques o efectos cuyo origen sea externo a la esfera, como tampoco puede una criatura situada dentro de la esfera dañar a algo en el exterior.\n\nLa esfera no pesa nada y es del tamaño justo para contener a la criatura u objeto. Una criatura encerrada puede utilizar su acción para empujar la esfera desde dentro, haciéndola rodar a una velocidad máxima que será la mitad de la velocidad de la criatura. De la misma forma, el globo puede ser levantado y movido por otras criaturas.\n\nUn conjuro de *desintegrar* que tenga como objetivo el globo lo destruirá sin dañar nada albergado dentro del mismo.",
        mechanics = "Si el objetivo falla salvación de Destreza, queda encerrado. Nada fisico ni mágico atraviesa la barrera, aunque la esfera puede moverse empujandola. El objetivo queda protegido y atrapado a la vez.",
        roleNotes = "Una burbuja perfecta separa al objetivo del mundo.",
