        description = "Un espíritu de la naturaleza responde a tu llamado y te transforma en un guardián poderoso. La transformación dura hasta que el conjuro termina. Eliges una de las siguientes formas para asumir: Bestia Primigenia o Gran Árbol.\n\nBestia Primigenia. Un pelaje bestial cubre tu cuerpo, tus rasgos faciales se vuelven salvajes y obtienes los siguientes beneficios:\n\nTu velocidad de movimiento aumenta en 3 metros. Obtienes visión oscura con un alcance de 36,6 metros. Haces tiradas de ataque basadas en la Fuerza con ventaja. Tus ataques de arma cuerpo a cuerpo provocan daño adicional de 1d6 de fuerza al golpear. Gran Árbol. Tu piel parece como de corteza, brotan hojas de tu cabello, y obtienes los siguientes beneficios:\n\nGanas 10 puntos de golpe temporales. Realizas tiradas de salvación de Constitución con ventaja. Haces tiradas de ataque basadas en Destreza y Sabiduría con ventaja. Mientras estás en el suelo, el suelo hasta a 4,6 metros de ti es terreno difícil para tus enemigos.",
