    {
        id = "invocar_aberracion",
        name = "Invocar aberracion",
        level = 4,
        school = "Conjuracion",
        affinity = "Arcano",
        classes = { "Brujo" },
        categories = { "Utilidad" },
        castingTime = "1 accion",
        range = "27 metros",
        components = "V, S, M",
        duration = "Concentracion, hasta 1 hora",
        concentration = true,
        ritual = false,
        savingThrow = "",
        attack = "Invocacion",
        damage = "Variable",
        sourceGroup = "DnD",
        source = "DnD",
        icon = 136633,
        description = "Invocas un espíritu aberrante, el cual se manifiesta en un espacio desocupado que puedes ver dentro del alcance. Esta forma corpórea usa el perfil Espíritu Aberrante. Cuando lances el conjuro, elige Contempladores, Slaad o Engendro estelar. La criatura se parece a una aberración de ese tipo, que determina ciertos atributos en su perfil. La criatura desaparece cuando cae a 0 puntos de golpe o cuando termina el conjuro. La criatura es un aliado para ti y tus compañeros. En combate, la criatura comparte tu orden de iniciativa, pero toma su turno inmediatamente después del tuyo. Obedece tus órdenes verbales (no necesitas invertir ninguna acción para hacer esto). Si no le das una orden, realiza la acción de Esquivar y usa su movimiento para evitar el peligro.\n\n***A Niveles Superiores.*** Cuando lanzas este conjuro usando un espacio de conjuro de nivel 5 o más, usa el nivel más alto donde se mencione el nivel de conjuro en el perfil de la criatura.\n\n*Aberración Mediana*\n\n**Clase de Armadura** 11 + el nivel del conjuro (armadura natural) **Puntos de Golpe** 40 + 10 por cada nivel de conjuro por encima de 4 **Velocidad** 9,1 metros, volar 9,1 metros (levitar) (solo Contempladores)\n\n**FUE DES CON INT SAB CAR** 16 (+3) 10 (+0) 15 (+2) 16 (+3) 10 (+0) 6 (-2)\n\n**Inmunidad al Daño** psíquico **Sentidos** visión en la oscuridad 18,3 metros, Percepción pasiva 10 **Idiomas** habla de las profundidades, comprende los idiomas que hablas **Desafío -- Bonificador de competencia** igual al tuyo\n\n***Regeneración (Solo Slaad).*** Si la aberración tiene al menos 1 punto de golpe al principio de su turno, recupera 5 puntos del golpe.\n\n***Aura Susurrante (Solo Engendros Estelares).*** Al principio de cada uno de los turnos de la aberración, cada criatura a 1,5 metros o menos de la aberración deberá superar una tirada de salvación de Sabiduría contra tu CD de salvación de conjuros o recibirán 2d6 de daño psíquico, siempre y cuando la aberración no esté incapacitada.\n\nAcciones\n\n***Ataque Múltiple.*** La aberración hace tantos ataques como la mitad del nivel de este conjuro (redondeado a la baja).\n\n***Garras (Solo Slaad). Ataque con arma cuerpo a cuerpo:* tu modificador de ataque de conjuros a impactar, alcance 1,5 metros, un objetivo. *Impacto:* 1d10 + 3 + el nivel del conjuro de daño cortante. Si el objetivo es una criatura, no puede recuperar puntos de golpe hasta el inicio del próximo turno de la aberración.\n\n***Rayo Ocular (Solo Contempladores). Ataque de conjuro a distancia:* tu modificador de ataque de conjuros a impactar, alcance 45,7 metros, una criatura. *Impacto:* 1d8 + 3 + el nivel del conjuro de daño psíquico.\n\n***Golpe Psíquico (Solo Engendros Estelares). Ataque de conjuro cuerpo a cuerpo:* tu modificador de ataque de conjuros a impactar, alcance 1,5 metros, una criatura. *Impacto:* 1d8 + 3 + el nivel del conjuro de daño de psíquico.",
        mechanics = "El espíritu aparece en un espacio libre y usa una forma elegida, como contemplador, slaad o engendro estelar. Obedece tus órdenes y mejora si lanzas el conjuro con niveles superiores.",
        roleNotes = "Algo que no pertenece del todo a este mundo responde a tu llamada.",
    },
