        concentration = true,
        ritual = false,
        savingThrow = "",
        attack = "Invocacion peligrosa",
        damage = "Variable",
        sourceGroup = "DnD",
        source = "DnD",
        icon = 136634,
        description = "Pronuncias palabras desagradables, convocando a un demonio desde el caos del Abismo. Eliges el tipo de demonio, que debe ser uno de clasificación de desafío 5 o inferior, como un demonio de la sombra o un barlgura. El demonio aparece en un espacio desocupado que puedes ver dentro del alcance, y el demonio desaparece cuando cae a 0 puntos de golpe o cuando termina el conjuro.\n\nTira iniciativa para el demonio, que tiene sus propios turnos. Cuando lo convocas y en cada uno de sus turnos posteriores, puedes emitirle un comando verbal (que no requiere ninguna acción de tu parte), diciéndole lo que debe hacer en su próximo turno. Si no emites ningún comando, pasa su turno atacando a cualquier criatura al alcance que lo haya atacado.\n\nAl final de cada uno de los turnos del demonio, este hace una tirada de salvación de Carisma. El demonio tiene desventaja en esta tirada de salvación si dices su nombre verdadero. En una salvación fallida, el demonio continúa obedeciéndote. En una salvación exitosa, tu control del demonio termina por el resto de la duración, y el demonio pasa sus turnos persiguiendo y atacando a los no demonios más cercanos lo mejor que pueda. Si dejas de concentrarte en el conjuro antes de que alcance su duración completa, un demonio incontrolado no desaparecerá durante 1d6 rondas si aún tiene puntos de golpe.\n\nComo parte de lanzar el conjuro, puedes formar un círculo en el suelo con la sangre utilizada como componente material. El círculo es lo suficientemente grande como para abarcar tu espacio. Mientras dura el conjuro, el demonio invocado no puede cruzar el círculo ni dañarlo, y no puede atacar a nadie dentro de él. Usar el componente material de esta manera lo consume cuando termina el conjuro.\n\nA niveles superiores. Cuando lanzas este conjuro usando un espacio de conjuro de 5to nivel o superior, el índice de desafío aumenta en 1 por cada nivel de espacio de conjuro por encima del 4º.",
        mechanics = "Invocas un demonio de desafío apropiado. Obedece mientras controles el conjuro, pero puede realizar salvaciones para liberarse. Si pierdes concentración, no desaparece de inmediato y puede actuar por su cuenta.",
        roleNotes = "Un pacto momentaneo con una violencia que apenas acepta cadenas.",
