        sourceGroup = "DnD",
        source = "Reglas basicas",
        icon = 135451,
        description = "Creas un fantasma ilusorio que se asienta en la mente de una criatura que puedas ver dentro del alcance. El objetivo debe hacer una tirada de salvación de Inteligencia. Si fracasa, creas hasta el final de la duración del conjuro un objeto, criatura u otro fenómeno visible de tu elección que solo el objetivo podrá ver. Tiene un aspecto fantasmal y su tamaño no puede ser mayor que un cubo de 3 metros de lado. Este conjuro no afecta a muertos vivientes o autómatas.\n\nEl fantasma puede emitir sonidos, alterar la temperatura y producir otros estímulos, todos ellos visibles únicamente para el objetivo.\n\nSi la criatura utiliza su acción para examinar la imagen, podrá determinar que es una ilusión si tiene éxito en una prueba de Inteligencia (Investigación) cuya CD es tu salvación de conjuros. Si tiene éxito en la prueba, el objetivo se da cuenta de que el fantasma es una ilusión y el conjuro termina.\n\nMientras el objetivo permanezca afectado por el conjuro, tratará al fantasma como si fuera real. Racionalizará cualquier resultado ilógico producto de interactuar con el fantasma. Por ejemplo, un objetivo de este conjuro que camine sobre un puente ilusorio que cruza un abismo, caerá en cuanto dé el primer paso. Pero si el objetivo sobrevive a la caída, todavía creerá que **el** puente existe e inventará una explicación para su caída (fue empujado, se resbaló o quizá un fuerte viento lo arrojó al vacío).\n\nEl objetivo afectado está tan convencido de la existencia real de la ilusión que incluso puede llegar a sufrir daño de esta. Un fantasma creado para parecer una criatura puede atacar al objetivo. De forma similar, un fantasma creado para parecer fuego, un charco de ácido o lava podría quemar al objetivo. Cada asalto, en tu turno, el fantasma puede infligir 1d6 de daño psíquico al objetivo si está en el área ocupada por el fantasma o a 1,5 metros del mismo. Para ello, es necesario que la ilusión sea de una criatura o peligro que pudiera causar daño de forma lógica, como por ejemplo atacando. El objetivo percibe el daño como de un tipo apropiado a la ilusión.",
        mechanics = "El objetivo hace salvación de Inteligencia. Fallo: cree en la ilusion y racionaliza sus efectos. Si la ilusion puede causarle daño, recibe 1d6 psíquico por turno.",
