        sourceGroup = "DnD",
        source = "Tasha",
        icon = 135451,
        description = "Invocas un espíritu sombrío, el cual se manifiesta en un espacio desocupado que puedes ver dentro del alcance. Esta forma corpórea usa el perfil Espíritu Sombrío. Cuando lances el conjuro, elige una emoción: Furia, Desesperación o Miedo. La criatura se asemeja a un bípedo deforme marcado por la emoción elegida, la cual determina ciertos atributos en su perfil. La criatura desaparece cuando cae a 0 puntos de golpe o cuando termina el conjuro. La criatura es un aliado para ti y tus compañeros. En combate, la criatura comparte tu orden de iniciativa, pero toma su turno inmediatamente después del tuyo. Obedece tus órdenes verbales (no necesitas invertir ninguna acción para hacer esto). Si no le das una orden, realiza la acción de Esquivar y usa su movimiento para evitar el peligro.\n\n***A Niveles Superiores.*** Cuando lanzas este conjuro usando un espacio de conjuro de nivel 4 o más, usa el nivel más alto donde se mencione el nivel de conjuro en el perfil de la criatura. *Monstruosidad Mediana*\n\n**Clase de Armadura** 11 + el nivel del conjuro (armadura natural) **Puntos de Golpe** 35 + 15 por cada nivel de conjuro por encima de 3 **Velocidad** 12,2 metros\n\n**FUE DES CON INT SAB CAR** 13 (+1) 16 (+3) 15 (+2) 4 (-3) 10 (+0) 16 (+3)\n\n**Resistencia al Daño** necrótico **Inmunidad a Estados** asustado **Sentidos** visión en la oscuridad 36,6 metros, Percepción pasiva 10 **Idiomas** comprende los idiomas que hablas **Desafío -- Bonificador de competencia** igual al tuyo\n\n***Frenesí del Terror (Solo Furia).*** El espíritu tiene ventaja en tiradas de ataque contra criaturas asustadas.\n\n***Peso del Dolor (Solo Desesperación).*** Cualquier criatura, que no seas tú, que inicie su turno a 1,5 metros o menos del espíritu verá su velocidad reducida en 6,1 metros hasta el inicio del próximo turno de esa criatura.\n\nAcciones\n\n***Ataque Múltiple.*** El espíritu hace tantos ataques como la mitad del nivel de este conjuro (redondeado a la baja).\n\n***Desgarro Gélido. Ataque con arma cuerpo a cuerpo:* tu modificador de ataque de conjuros a impactar, alcance 1,5 metros, un objetivo. *Impacto:* 1d12 + 3 + el nivel del conjuro de daño de frío.\n\n***Grito Terrorífico (1/día).*** El espíritu grita. Cada criatura a 9,1 metros o menos de él deberá superar una tirada de salvación de Sabiduría contra tu CD de salvación de conjuros o quedará asustada del espíritu por 1 minuto. La criatura puede repetir la tirada de salvación al final de cada uno de sus turnos, terminando el efecto sobre sí misma si la supera.\n\nAcción Adicional\n\n***Sigilo Sombrío (Solo Miedo).*** Mientras está en luz tenue u oscuridad, el espíritu realiza la acción de Esconderse.",
